import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Sintaxis de búsqueda","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/search-syntax.md","filePath":"es-ES/user-guide/search-syntax.md","lastUpdated":1787649438000}'),d={name:"es-ES/user-guide/search-syntax.md"};function s(n,e,c,r,l,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="sintaxis-de-busqueda" tabindex="-1">Sintaxis de búsqueda <a class="header-anchor" href="#sintaxis-de-busqueda" aria-label="Permalink to &quot;Sintaxis de búsqueda&quot;">​</a></h1><p>La barra de búsqueda de Lertaro admite mucho más que una simple búsqueda de texto plano. Equipada con un algoritmo de coincidencia ultrarrápido, admite coincidencia difusa con salto de caracteres, operadores lógicos, modificadores de límite de palabra, delimitación por unidad y ruta, fichas de consulta (Query Tokens) para filtrado secundario y alias multilingües inteligentes. Todas las sintaxis se pueden combinar libremente en la misma consulta.</p><h2 id="_1-modos-de-coincidencia-basica-y-distincion-entre-mayusculas-y-minusculas" tabindex="-1">1. Modos de coincidencia básica y distinción entre mayúsculas y minúsculas <a class="header-anchor" href="#_1-modos-de-coincidencia-basica-y-distincion-entre-mayusculas-y-minusculas" aria-label="Permalink to &quot;1. Modos de coincidencia básica y distinción entre mayúsculas y minúsculas&quot;">​</a></h2><h3 id="coincidencia-difusa-predeterminada" tabindex="-1">Coincidencia difusa (predeterminada) <a class="header-anchor" href="#coincidencia-difusa-predeterminada" aria-label="Permalink to &quot;Coincidencia difusa (predeterminada)&quot;">​</a></h3><p>Lertaro activa la coincidencia difusa (Fuzzy Matching) de forma predeterminada. Simplemente escribe cualquier parte de las palabras y coincidirá siempre que los caracteres aparezcan en orden en el nombre del archivo o carpeta, incluso si no son continuos:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ejemplo de entrada</th><th style="text-align:left;">Resultado de coincidencia</th><th style="text-align:left;">Descripción</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ltro</code></td><td style="text-align:left;"><code>Lertaro.exe</code></td><td style="text-align:left;">Los caracteres coinciden en orden: <code>l</code> → <code>t</code> → <code>r</code> → <code>o</code> (<strong>L</strong>er<strong>t</strong>a<strong>ro</strong>.exe)</td></tr><tr><td style="text-align:left;"><code>vsc</code></td><td style="text-align:left;"><code>Visual Studio Code.lnk</code></td><td style="text-align:left;">Coincide con las iniciales de cada palabra (<strong>V</strong>isual <strong>S</strong>tudio <strong>C</strong>ode)</td></tr><tr><td style="text-align:left;"><code>rt-fin</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td><td style="text-align:left;">Coincide con la subcadena continua (Q3-repo<strong>rt-fin</strong>al.docx)</td></tr></tbody></table><p>Desactiva esta opción en <strong>Configuración → General → Sistema → Habilitar coincidencia difusa</strong> y los términos de búsqueda simples (sin operadores) requerirán una subcadena continua — <code>abc</code> solo coincidirá con nombres que contengan <code>abc</code> continuo, ya no con <code>a-b-c</code>. Esta opción solo afecta a los términos simples; todos los operadores descritos a continuación mantienen su comportamiento exacto.</p><h3 id="distincion-inteligente-de-mayusculas-y-minusculas-smart-case" tabindex="-1">Distinción inteligente de mayúsculas y minúsculas (Smart Case) <a class="header-anchor" href="#distincion-inteligente-de-mayusculas-y-minusculas-smart-case" aria-label="Permalink to &quot;Distinción inteligente de mayúsculas y minúsculas (Smart Case)&quot;">​</a></h3><ul><li><strong>Consultas en minúsculas</strong>: No distinguen entre mayúsculas y minúsculas por defecto. Por ejemplo, <code>myfile</code> coincide con <code>myfile</code>, <code>MyFile</code>, <code>MYFILE</code>, etc.</li><li><strong>Consultas con letras mayúsculas</strong>: Una vez que un término contiene cualquier letra mayúscula, se vuelve automáticamente <strong>sensible a las mayúsculas</strong>. Por ejemplo, <code>MyFile</code> solo coincide con <code>MyFile</code>, y no con <code>myfile</code> en minúsculas.</li></ul><h2 id="_2-varios-terminos-y-operadores-logicos" tabindex="-1">2. Varios términos y operadores lógicos <a class="header-anchor" href="#_2-varios-terminos-y-operadores-logicos" aria-label="Permalink to &quot;2. Varios términos y operadores lógicos&quot;">​</a></h2><h3 id="espacio-and-y" tabindex="-1">Espacio: AND (Y) <a class="header-anchor" href="#espacio-and-y" aria-label="Permalink to &quot;Espacio: AND (Y)&quot;">​</a></h3><p>Separa varios términos de búsqueda con espacios para exigir que se cumplan todas las condiciones. El orden en el que aparecen los términos en el nombre del archivo <strong>no importa</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final 2024</span></span></code></pre></div><p>La consulta anterior coincide tanto con <code>2024-Q3-report-final.docx</code> como con <code>final_report_2024.pdf</code>.</p><h3 id="barra-vertical-or-o" tabindex="-1">Barra vertical <code>|</code>: OR (O) <a class="header-anchor" href="#barra-vertical-or-o" aria-label="Permalink to &quot;Barra vertical `|`: OR (O)&quot;">​</a></h3><p>Usa el símbolo de barra vertical <code>|</code> para separar términos cuando baste con que coincida cualquiera de las alternativas:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>png | jpg | gif</span></span></code></pre></div><p>Puedes combinar libremente la lógica AND y OR:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024</span></span></code></pre></div><p>Esto busca archivos que contengan <code>report</code> o <code>summary</code>, y que además contengan <code>2024</code>. En las consultas OR, todos los términos que coincidan se resaltarán simultáneamente en el nombre del resultado.</p><h3 id="precedencia-de-operadores-or-se-agrupa-mas-estrechamente-que-and" tabindex="-1">Precedencia de operadores: OR se agrupa más estrechamente que AND <a class="header-anchor" href="#precedencia-de-operadores-or-se-agrupa-mas-estrechamente-que-and" aria-label="Permalink to &quot;Precedencia de operadores: OR se agrupa más estrechamente que AND&quot;">​</a></h3><p>Cuando se mezclan espacios (AND) y la barra vertical <code>|</code> (OR) en una misma consulta, <code>|</code> tiene <strong>mayor</strong> prioridad que los espacios: los términos de ambos lados de <code>|</code> se agrupan primero en un único grupo OR, y los grupos separados por espacios se combinan después con AND. No se admiten paréntesis, por lo que este orden de agrupación no se puede cambiar.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024 | draft</span></span></code></pre></div><p>equivale a <code>(report OR summary) AND (2024 OR draft)</code>.</p><p>Nota: <code>|</code> debe ser un token independiente con espacios a ambos lados: <code>a|b</code> o <code>a |b</code> no se interpreta como OR. Tampoco metas un término de exclusión <code>!</code> dentro de un grupo OR (p. ej. <code>b | !c</code>), que se interpreta como «b coincide o c no coincide»; para excluir un término globalmente, dale su propia condición AND separada por espacios (p. ej. <code>b !c</code>).</p><h3 id="espacios-en-terminos-y-frases-entre-comillas" tabindex="-1">Espacios en términos y frases entre comillas <a class="header-anchor" href="#espacios-en-terminos-y-frases-entre-comillas" aria-label="Permalink to &quot;Espacios en términos y frases entre comillas&quot;">​</a></h3><p>Para buscar una frase que contenga espacios dentro de un solo término, escapa el espacio con una barra invertida <code>\\ </code>, o encierra la frase entre comillas simples <code>&#39;...&#39;</code> o dobles <code>&quot;...&quot;</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>final\\ report</span></span>\n<span class="line"><span>&#39;final report&#39;</span></span></code></pre></div><p>Ambas formas tratan <code>final report</code> como una frase única con espacio, en lugar de dividirla en dos términos AND independientes.</p><h3 id="pegar-texto-de-varias-lineas-doblado-en-or" tabindex="-1">Pegar texto de varias líneas doblado en OR <a class="header-anchor" href="#pegar-texto-de-varias-lineas-doblado-en-or" aria-label="Permalink to &quot;Pegar texto de varias líneas doblado en OR&quot;">​</a></h3><p>Al copiar texto de varias líneas (por ejemplo, nombres de archivo de una hoja de cálculo, archivo de texto o registro) y pegarlo directamente en el cuadro de búsqueda, Lertaro dobla automáticamente las líneas en una única consulta OR separada por <code>|</code> (las líneas en blanco se omiten automáticamente):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>\n<span class="line"><span>456</span></span>\n<span class="line"><span>678</span></span></code></pre></div><p>Se pega automáticamente como:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123 | 456 | 678</span></span></code></pre></div><h2 id="_3-tabla-resumen-de-operadores-de-busqueda" tabindex="-1">3. Tabla resumen de operadores de búsqueda <a class="header-anchor" href="#_3-tabla-resumen-de-operadores-de-busqueda" aria-label="Permalink to &quot;3. Tabla resumen de operadores de búsqueda&quot;">​</a></h2><h3 id="tabla-de-operadores" tabindex="-1">Tabla de operadores <a class="header-anchor" href="#tabla-de-operadores" aria-label="Permalink to &quot;Tabla de operadores&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Operador / Sintaxis</th><th style="text-align:left;">Tipo</th><th style="text-align:left;">Descripción</th><th style="text-align:left;">Ejemplo de entrada</th><th style="text-align:left;">Ejemplo de coincidencia</th></tr></thead><tbody><tr><td style="text-align:left;"><em>(ninguno)</em></td><td style="text-align:left;">Difuso predeterminado</td><td style="text-align:left;">Los caracteres aparecen en orden en cualquier parte del nombre</td><td style="text-align:left;"><code>report</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td></tr><tr><td style="text-align:left;"><code>!</code></td><td style="text-align:left;">Excluir</td><td style="text-align:left;">Excluye todos los resultados cuyo nombre contenga esta subcadena exacta</td><td style="text-align:left;"><code>!temp</code></td><td style="text-align:left;">Filtra archivos que contengan <code>temp</code></td></tr><tr><td style="text-align:left;"><code>&#39;</code></td><td style="text-align:left;">Invertir exactitud</td><td style="text-align:left;">Subcadena exacta si el modo difuso está activo; difuso si está apagado</td><td style="text-align:left;"><code>&#39;report</code></td><td style="text-align:left;">Debe contener la subcadena continua <code>report</code></td></tr><tr><td style="text-align:left;"><code>&#39;...&#39;</code></td><td style="text-align:left;">Límite de palabra</td><td style="text-align:left;">Subcadena exacta en límites de palabra (no dentro de palabras más largas)</td><td style="text-align:left;"><code>&#39;app&#39;</code></td><td style="text-align:left;">Coincide con <code>app.exe</code>, <code>my-app.log</code>; no con <code>whatsapp.exe</code></td></tr><tr><td style="text-align:left;"><code>^</code></td><td style="text-align:left;">Coincidencia de prefijo</td><td style="text-align:left;">El nombre debe comenzar con este texto</td><td style="text-align:left;"><code>^IMG</code></td><td style="text-align:left;"><code>IMG_20240101.jpg</code> (no coincide con <code>MY_IMG.jpg</code>)</td></tr><tr><td style="text-align:left;"><code>$</code></td><td style="text-align:left;">Coincidencia de sufijo</td><td style="text-align:left;">El nombre debe terminar con este texto</td><td style="text-align:left;"><code>.pdf$</code></td><td style="text-align:left;"><code>document.pdf</code> (no coincide con <code>document.pdf.bak</code>)</td></tr><tr><td style="text-align:left;"><code>^...$</code></td><td style="text-align:left;">Coincidencia exacta</td><td style="text-align:left;">El nombre debe ser exactamente igual a este texto</td><td style="text-align:left;"><code>^readme.md$</code></td><td style="text-align:left;">Coincide únicamente con <code>readme.md</code></td></tr><tr><td style="text-align:left;"><code>|</code></td><td style="text-align:left;">Lógica OR</td><td style="text-align:left;">Coincide con cualquiera de los lados de la barra</td><td style="text-align:left;"><code>doc | pdf</code></td><td style="text-align:left;">Coincide con nombres que contengan <code>doc</code> o <code>pdf</code></td></tr></tbody></table><h3 id="comportamiento-detallado-de-operadores-y-combinaciones" tabindex="-1">Comportamiento detallado de operadores y combinaciones <a class="header-anchor" href="#comportamiento-detallado-de-operadores-y-combinaciones" aria-label="Permalink to &quot;Comportamiento detallado de operadores y combinaciones&quot;">​</a></h3><ol><li><strong>Exclusión <code>!</code></strong>: <code>!term</code> descarta directamente los resultados que contengan <code>term</code> como subcadena exacta. Los términos excluidos no se expanden con pinyin ni alias para evitar exclusiones accidentales.</li><li><strong>Inversión de exactitud <code>&#39;</code></strong>: Cuando la coincidencia difusa global está activada, anteponer <code>&#39;</code> fuerza a un término específico a coincidir como subcadena continua exacta. <ul><li>Por ejemplo, <code>lertaro &#39;v1.2</code> busca <code>lertaro</code> de forma difusa mientras que exige <code>v1.2</code> de forma continua y exacta.</li><li>Los términos exactos siguen coincidiendo con nombres de archivo que tienen alias en pinyin: <code>&#39;exe$</code> también encuentra <code>古恩希尔</code>, cuyo pinyin se asigna a <code>gexe</code>.</li></ul></li><li><strong>Límite de palabra <code>&#39;...&#39;</code></strong>: Encerrar una palabra entre comillas (por ejemplo, <code>&#39;app&#39;</code>) verifica los límites anteriores y posteriores (espacios, signos de puntuación, guiones, guiones bajos o extremos de cadena), evitando falsos positivos dentro de palabras largas.</li><li><strong>Coincidencia exacta <code>^...$</code></strong>: Solo se aplica cuando <code>^</code> y <code>$</code> envuelven la <strong>misma palabra</strong>. Si se escriben en palabras separadas (por ejemplo, <code>^src md$</code>), siguen actuando como filtros independientes de prefijo y sufijo.</li></ol><p><strong>Ejemplos de combinación de operadores</strong>:</p><ul><li><code>^IMG !.png$ 2024</code>: Busca archivos que comiencen por <code>IMG</code>, contengan <code>2024</code> y <strong>no</strong> terminen en <code>.png</code>.</li><li><code>&#39;data | &#39;backup ^2024 .zip$</code>: Busca archivos comprimidos que comiencen por <code>2024</code>, terminen en <code>.zip</code> y contengan la subcadena exacta <code>data</code> o <code>backup</code>.</li><li><code>^report &#39;公告 | &#39;gw .pdf$ !draft</code>: Busca nombres que empiecen por <code>report</code>, terminen en <code>.pdf</code>, no contengan <code>draft</code> y contengan exactamente <code>公告</code>, <code>gw</code>, <code>公文</code> u otras combinaciones que coincidan con el pinyin <code>gw</code> (<code>&#39;公告 | &#39;gw</code> forma un grupo OR; el resto de condiciones separadas por espacios se combinan con AND).</li></ul><h2 id="_4-modo-de-ruta-y-delimitacion-por-unidad" tabindex="-1">4. Modo de ruta y delimitación por unidad <a class="header-anchor" href="#_4-modo-de-ruta-y-delimitacion-por-unidad" aria-label="Permalink to &quot;4. Modo de ruta y delimitación por unidad&quot;">​</a></h2><h3 id="especificar-una-unidad" tabindex="-1">Especificar una unidad <a class="header-anchor" href="#especificar-una-unidad" aria-label="Permalink to &quot;Especificar una unidad&quot;">​</a></h3><p>Comienza la consulta con una letra de unidad seguida de dos puntos para limitar los resultados estrictamente a esa unidad:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>El espacio es opcional: <code>d:report</code> y <code>d: report</code> son equivalentes.</p><h3 id="modo-de-ruta-completa" tabindex="-1">Modo de ruta completa <a class="header-anchor" href="#modo-de-ruta-completa" aria-label="Permalink to &quot;Modo de ruta completa&quot;">​</a></h3><p>Cuando la consulta contiene separadores de ruta (<code>\\</code> o <code>/</code>), Lertaro cambia automáticamente al modo de coincidencia de ruta completa:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>Si termina con un separador de ruta (por ejemplo, <code>D:\\Projects\\</code>), busca el contenido directo <strong>dentro</strong> de esa carpeta.</p><h3 id="coincidencia-alternativa-en-carpetas-superiores-folder-matching" tabindex="-1">Coincidencia alternativa en carpetas superiores (Folder Matching) <a class="header-anchor" href="#coincidencia-alternativa-en-carpetas-superiores-folder-matching" aria-label="Permalink to &quot;Coincidencia alternativa en carpetas superiores (Folder Matching)&quot;">​</a></h3><p>Cuando la búsqueda solo por nombre de archivo no llena la capacidad de resultados, Lertaro utiliza automáticamente los términos no coincidentes para buscar coincidencias en las carpetas superiores sin necesidad de sintaxis especial:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p>Incluso si <code>dcj</code> nunca aparece en el propio nombre del archivo, Lertaro encuentra <code>d01j.txt</code> ubicado dentro de una carpeta llamada (o con alias) <code>dcj</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Esto requiere que al menos un término coincida con el nombre del archivo, y solo se activa cuando las coincidencias directas no llenan los resultados. Los resultados de respaldo siempre se ordenan después de las coincidencias directas.</p></div><h2 id="_5-fichas-de-consulta-y-filtrado-secundario-query-tokens" tabindex="-1">5. Fichas de consulta y filtrado secundario (Query Tokens) <a class="header-anchor" href="#_5-fichas-de-consulta-y-filtrado-secundario-query-tokens" aria-label="Permalink to &quot;5. Fichas de consulta y filtrado secundario (Query Tokens)&quot;">​</a></h2><p>Lertaro permite añadir <strong>fichas de consulta (Query Tokens)</strong> encabezadas por dos puntos <code>:</code> (personalizable en <strong>Configuración → General → Sistema → Carácter de prefijo global de token de consulta</strong>) al final de la búsqueda para realizar filtrados y ordenaciones secundarias en cadena.</p><p>Puedes combinar varias fichas tras un solo prefijo <code>:</code> separándolas por comas <code>,</code>, como en <code>report :@doc,M-,:-F</code>.</p><h3 id="filtros-de-categoria-de-archivo-categoria" tabindex="-1">Filtros de categoría de archivo (<code>:@&lt;categoría&gt;</code>) <a class="header-anchor" href="#filtros-de-categoria-de-archivo-categoria" aria-label="Permalink to &quot;Filtros de categoría de archivo (`:@&lt;categoría&gt;`)&quot;">​</a></h3><p>Aplica rápidamente reglas preestablecidas de extensión de archivo, admitiendo combinaciones con <code>|</code>:</p><ul><li><code>:@doc</code>: Documentos (<code>*.doc; *.docx; *.pdf; *.txt; *.ppt; *.pptx; *.xls; *.xlsx; *.csv; *.rtf; *.md; *.wps</code>)</li><li><code>:@img</code>: Imágenes (<code>*.jpg; *.jpeg; *.png; *.gif; *.bmp; *.webp; *.ico; *.svg; *.tif; *.tiff; *.psd; *.ai</code>)</li><li><code>:@video</code>: Vídeos (<code>*.mp4; *.mkv; *.avi; *.mov; *.wmv; *.flv; *.m4v; *.webm; *.3gp; *.rmvb; *.ts</code>)</li><li><code>:@audio</code>: Audio (<code>*.mp3; *.wav; *.flac; *.aac; *.ogg; *.m4a; *.wma; *.ape</code>)</li><li><code>:@zip</code>: Archivos comprimidos (<code>*.zip; *.rar; *.7z; *.tar; *.gz; *.bz2; *.xz; *.iso</code>)</li></ul><p><strong>Ejemplos</strong>:</p><ul><li><code>financiero :@doc</code>: Busca &quot;financiero&quot; entre documentos.</li><li><code>wallpaper :@img</code>: Busca &quot;wallpaper&quot; entre imágenes.</li><li><code>clip :@video|audio</code>: Busca &quot;clip&quot; entre vídeos o archivos de audio.</li></ul><p>Puedes personalizar reglas o añadir nuevas categorías en <strong>Configuración → Plugins → CoreExtensions</strong>.</p><h3 id="filtros-por-extension-especifica-ext-o-ext1-ext2" tabindex="-1">Filtros por extensión específica (<code>:.ext</code> o <code>:.ext1.ext2</code>) <a class="header-anchor" href="#filtros-por-extension-especifica-ext-o-ext1-ext2" aria-label="Permalink to &quot;Filtros por extensión específica (`:.ext` o `:.ext1.ext2`)&quot;">​</a></h3><p>Usa un punto para especificar una o varias extensiones (excluye carpetas automáticamente):</p><ul><li><code>report :.pdf</code>: Conserva únicamente archivos <code>.pdf</code>.</li><li><code>data :.csv.xlsx</code>: Conserva únicamente archivos de hoja de cálculo <code>.csv</code> o <code>.xlsx</code>.</li></ul><h3 id="ordenacion-y-filtros-de-archivo-carpeta-scmaf" tabindex="-1">Ordenación y filtros de archivo/carpeta (<code>:[SCMAF]</code>) <a class="header-anchor" href="#ordenacion-y-filtros-de-archivo-carpeta-scmaf" aria-label="Permalink to &quot;Ordenación y filtros de archivo/carpeta (`:[SCMAF]`)&quot;">​</a></h3><p>Usa letras individuales para especificar atributos: <code>S</code> (Tamaño/Size), <code>C</code> (Creación/Created), <code>M</code> (Modificación/Modified), <code>A</code> (Acceso/Accessed), <code>F</code> (Carpeta/Folder).</p><p>La letra sin signo indica <strong>orden ascendente</strong> (menor tamaño / más antiguo primero); añadir un signo menos <code>-</code> (como prefijo o sufijo, por ejemplo, <code>M-</code> o <code>:-M</code>) indica <strong>orden descendente</strong> (mayor tamaño / más reciente primero) o filtrado inverso:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Sintaxis</th><th style="text-align:left;">Efecto</th><th style="text-align:left;">Escenario típico</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:S</code></td><td style="text-align:left;">Ordenar por tamaño ascendente (más pequeños primero)</td><td style="text-align:left;">Localizar archivos vacíos o diminutos</td></tr><tr><td style="text-align:left;"><code>:S-</code> o <code>:-S</code></td><td style="text-align:left;">Ordenar por tamaño descendente (más grandes primero)</td><td style="text-align:left;"><code>log :S-</code> (revisar archivos de registro enormes)</td></tr><tr><td style="text-align:left;"><code>:M</code></td><td style="text-align:left;">Ordenar por fecha de modificación ascendente (más antiguos)</td><td style="text-align:left;">Revisar archivos sin actualizar hace mucho</td></tr><tr><td style="text-align:left;"><code>:M-</code> o <code>:-M</code></td><td style="text-align:left;">Ordenar por fecha de modificación descendente (más recientes)</td><td style="text-align:left;"><code>report :M-</code> (encontrar documentos editados recientemente)</td></tr><tr><td style="text-align:left;"><code>:C</code> / <code>:C-</code></td><td style="text-align:left;">Ordenar por fecha de creación ascendente / descendente</td><td style="text-align:left;"><code>build :C-</code> (encontrar las compilaciones más recientes)</td></tr><tr><td style="text-align:left;"><code>:A</code> / <code>:A-</code></td><td style="text-align:left;">Ordenar por fecha de acceso ascendente / descendente</td><td style="text-align:left;"><code>project :A-</code> (encontrar proyectos abiertos recientemente)</td></tr><tr><td style="text-align:left;"><code>:F</code></td><td style="text-align:left;"><strong>Solo carpetas</strong> (excluye archivos normales)</td><td style="text-align:left;"><code>config :F</code> (buscar solo directorios llamados config)</td></tr><tr><td style="text-align:left;"><code>:-F</code> o <code>:F-</code></td><td style="text-align:left;"><strong>Solo archivos</strong> (excluye carpetas/directorios)</td><td style="text-align:left;"><code>config :-F</code> (buscar solo archivos llamados config)</td></tr></tbody></table><h3 id="filtros-secundarios-con-comodines-expresion-o-expresion" tabindex="-1">Filtros secundarios con comodines (<code>:?&lt;expresión&gt;</code> o <code>?&lt;expresión&gt;</code>) <a class="header-anchor" href="#filtros-secundarios-con-comodines-expresion-o-expresion" aria-label="Permalink to &quot;Filtros secundarios con comodines (`:?&lt;expresión&gt;` o `?&lt;expresión&gt;`)&quot;">​</a></h3><p>Usa comodines estándar de Windows (<code>?</code> para un carácter, <code>*</code> para cero o más caracteres) para una coincidencia precisa, admitiendo <code>|</code> o <code>;</code> para varias condiciones OR:</p><ul><li><code>mp4 :?(2026???????????)</code>: Coincide con archivos de vídeo con <code>2026</code> y una marca de tiempo de 11 dígitos.</li><li><code>photo :?IMG_????.jpg|DSC_????.jpg</code>: Coincide con números de foto específicos entre dos formatos de cámara.</li></ul><h3 id="filtros-secundarios-por-segmento-de-ruta-expresion" tabindex="-1">Filtros secundarios por segmento de ruta (<code>::&lt;expresión&gt;</code>) <a class="header-anchor" href="#filtros-secundarios-por-segmento-de-ruta-expresion" aria-label="Permalink to &quot;Filtros secundarios por segmento de ruta (`::&lt;expresión&gt;`)&quot;">​</a></h3><p>Requiere que los nombres de las carpetas superiores o el propio archivo coincidan con la palabra clave difusa:</p><ul><li><code>report ::2024</code>: Exige que la ruta contenga <code>2024</code>.</li><li><code>main ::&quot;src\\core&quot;</code>: Limita la búsqueda a archivos ubicados dentro de <code>src\\core</code> y sus subdirectorios.</li></ul><h3 id="ejemplos-de-fichas-encadenadas" tabindex="-1">Ejemplos de fichas encadenadas <a class="header-anchor" href="#ejemplos-de-fichas-encadenadas" aria-label="Permalink to &quot;Ejemplos de fichas encadenadas&quot;">​</a></h3><p>Las fichas se pueden combinar juntas tras un único prefijo <code>:</code>:</p><ul><li><code>informe :@doc,M-</code>: Busca &quot;informe&quot;, filtra por documentos y ordena por fecha de modificación descendente (más recientes primero).</li><li><code>backup :.zip,S-,:-F</code>: Busca &quot;backup&quot;, filtra por archivos <code>.zip</code>, ordena por tamaño de mayor a menor y muestra solo archivos.</li><li><code>icon ::assets,?*128*</code>: Busca &quot;icon&quot;, ubicado bajo rutas <code>assets</code> y con indicador de tamaño <code>128</code> en el nombre.</li></ul><h2 id="_6-funciones-especiales-de-busqueda" tabindex="-1">6. Funciones especiales de búsqueda <a class="header-anchor" href="#_6-funciones-especiales-de-busqueda" aria-label="Permalink to &quot;6. Funciones especiales de búsqueda&quot;">​</a></h2><h3 id="omitir-reglas-de-exclusion-en-una-sola-busqueda" tabindex="-1">Omitir reglas de exclusión en una sola búsqueda <a class="header-anchor" href="#omitir-reglas-de-exclusion-en-una-sola-busqueda" aria-label="Permalink to &quot;Omitir reglas de exclusión en una sola búsqueda&quot;">​</a></h3><p>Escribe <code>*</code> al principio de la consulta para ignorar temporalmente las rutas excluidas, globs y expresiones regulares configuradas en <a href="./settings/index-drives.html#reglas-de-exclusion"><strong>Reglas de exclusión</strong></a> para esa búsqueda puntual, sin modificar la configuración:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p>El <code>*</code> inicial se elimina automáticamente antes de la búsqueda. Solo recupera elementos que ya hayan sido indexados (las carpetas nunca indexadas en unidades de red o WSL no aparecerán); los filtros de archivos ocultos y del sistema permanecen activos.</p><h3 id="activador-de-tipo-de-resultado" tabindex="-1">Activador de tipo de resultado <a class="header-anchor" href="#activador-de-tipo-de-resultado" aria-label="Permalink to &quot;Activador de tipo de resultado&quot;">​</a></h3><p>En <strong>Configuración → General → Ventana de búsqueda rápida → Prioridad de tipo de resultado</strong>, puedes asignar un <strong>activador</strong> de un solo carácter a tipos de resultado específicos (Aplicaciones, Configuración, Categorías de archivo, Elementos de plugins, Archivos, etc.).</p><p>Escribir el activador como el primer carácter en la ventana de búsqueda rápida muestra únicamente los resultados de ese tipo, ocultando todos los demás:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>Si <code>;</code> está asignado a &quot;Aplicaciones&quot;, la consulta anterior buscará Visual Studio exclusivamente entre aplicaciones. En las ventanas rápida e incrustada, el Historial y los Favoritos permanecen fijados en la parte superior independientemente de los activadores.</p><h2 id="_7-alias-multilingues" tabindex="-1">7. Alias multilingües <a class="header-anchor" href="#_7-alias-multilingues" aria-label="Permalink to &quot;7. Alias multilingües&quot;">​</a></h2><h3 id="nombres-de-archivo-en-chino-alias-en-pinyin" tabindex="-1">Nombres de archivo en chino: alias en pinyin <a class="header-anchor" href="#nombres-de-archivo-en-chino-alias-en-pinyin" aria-label="Permalink to &quot;Nombres de archivo en chino: alias en pinyin&quot;">​</a></h3><p>Gracias al plugin integrado <code>PinyinAlias</code>, los nombres de archivo en chino se pueden buscar mediante pinyin sin necesidad de configuración:</p><ul><li><strong>Pinyin completo</strong>: Escribir <code>chongqing</code> coincide con <code>重庆.docx</code>.</li><li><strong>Iniciales de pinyin</strong>: Escribir <code>cq</code> también coincide con <code>重庆.docx</code>; escribir <code>wzry</code> coincide con <code>王者荣耀.exe</code>.</li><li><strong>Caracteres polifónicos</strong>: Las pronunciaciones habituales se indexan automáticamente (por ejemplo, <code>重庆</code> coincide con <code>chongqing</code> y <code>zhongqing</code>).</li></ul><p>Puedes verificar que <code>PinyinAlias</code> esté activo en <strong>Configuración → Plugins</strong>.</p><h3 id="nombres-de-archivo-en-espanol-alias-de-acentos" tabindex="-1">Nombres de archivo en español: alias de acentos <a class="header-anchor" href="#nombres-de-archivo-en-espanol-alias-de-acentos" aria-label="Permalink to &quot;Nombres de archivo en español: alias de acentos&quot;">​</a></h3><p>Con el plugin integrado <code>SpanishAlias</code>, los nombres de archivo que contienen caracteres con acento o tilde en español (<code>á</code>, <code>é</code>, <code>í</code>, <code>ó</code>, <code>ú</code>, <code>ü</code>, <code>ñ</code>) se pueden buscar directamente usando letras ASCII normales sin acentos:</p><ul><li>Escribir <code>cancion</code> coincide con <code>Canción.mp3</code>.</li><li>Escribir <code>nino</code> coincide con <code>Niño.txt</code>.</li><li>Escribir <code>ciguena</code> coincide con <code>Cigüeña.png</code>.</li></ul><p>Los caracteres coincidentes (incluidas las vocales acentuadas en el nombre original) se resaltan con precisión. Gestiona el plugin en <strong>Configuración → Plugins</strong>.</p><h2 id="_8-preguntas-frecuentes-y-favoritos" tabindex="-1">8. Preguntas frecuentes y Favoritos <a class="header-anchor" href="#_8-preguntas-frecuentes-y-favoritos" aria-label="Permalink to &quot;8. Preguntas frecuentes y Favoritos&quot;">​</a></h2><h3 id="favoritos-no-alias-personalizados" tabindex="-1">Favoritos, no alias personalizados <a class="header-anchor" href="#favoritos-no-alias-personalizados" aria-label="Permalink to &quot;Favoritos, no alias personalizados&quot;">​</a></h3><p>Lertaro no dispone de un sistema genérico de &quot;alias/macros de búsqueda personalizados&quot;. La solución nativa más cercana es <a href="./settings/favorites.html"><strong>Favoritos</strong></a>: fija cualquier archivo, carpeta o URL con un nombre de visualización personalizado y podrás buscarlo directamente por ese título (marcado con un icono ★ en los resultados).</p><p>Si deseas ejecutar programas o scripts mediante palabras clave personalizadas, consulta <a href="./instant-answers.html#comandos-personalizados"><strong>Comandos personalizados</strong></a>.</p>',103)])])}const g=a(d,[["render",s]]);export{m as __pageData,g as default};
